USE careloop_clinics;
-- NO-SHOW GUARD - CARELOOP CLINICS
-- Generated from cleaned Python datasets


DROP TABLE IF EXISTS `appointments`;
CREATE TABLE `appointments` (
  `appointment_id` VARCHAR(255),
  `patient_id` VARCHAR(255),
  `clinic_id` VARCHAR(255),
  `booked_on` DATE,
  `appt_date` DATE,
  `age` DOUBLE,
  `gender` VARCHAR(255),
  `distance_km` DOUBLE,
  `fee_inr` INT,
  `booking_channel` VARCHAR(255),
  `visit_type` VARCHAR(255),
  `reminder_sent` VARCHAR(255),
  `prior_no_shows` INT,
  `status` VARCHAR(255),
  `no_show` INT,
  `lead_days` INT
);


DROP TABLE IF EXISTS `clinics`;
CREATE TABLE `clinics` (
  `clinic_id` VARCHAR(255),
  `clinic_name` VARCHAR(255),
  `city` VARCHAR(255),
  `tier` VARCHAR(255),
  `latitude` DOUBLE,
  `longitude` DOUBLE,
  `avg_temperature` DOUBLE,
  `avg_max_temperature` DOUBLE,
  `avg_min_temperature` DOUBLE,
  `total_precipitation_mm` DOUBLE,
  `avg_wind_speed` DOUBLE,
  `rainy_days` INT
);


DROP TABLE IF EXISTS `clinic_daily_weather`;
CREATE TABLE `clinic_daily_weather` (
  `clinic_id` VARCHAR(255),
  `clinic_name` VARCHAR(255),
  `city` VARCHAR(255),
  `date` DATE,
  `temperature_mean` DOUBLE,
  `temperature_max` DOUBLE,
  `temperature_min` DOUBLE,
  `precipitation_mm` DOUBLE,
  `wind_speed_max` DOUBLE,
  `weather_code` INT
);
